import { memo, useEffect, useRef } from 'react';
import { useDroppable } from '@dnd-kit/core';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Tooltip } from '../common/Tooltip';
import { MENU_CYCLE_MESSAGE, MENU_DEPTH_LIMIT_REACHED_MESSAGE } from '../../store/projectModel/menuDepth.js';
import { NodeIcon } from '../icons/NodeIcon.jsx';
import { hierarchicalNatureOf } from '../../store/nodeIconVocabulary.js';
import { WORKSPACE_MODE_HIERARCHICAL } from '../../store/projectWorkState.js';
import {
  ArrowRight, ChevronRight, CornerUpLeft, Diamond, House, ListTree, Moon, Square, UnfoldVertical,
} from '../icons/LucideLocal';
import { getTreeGuideStyleVars, getTreeIndent, resolveHoverGuide } from './treeGuides';
import './TreePanel.css';
import './TreeGuides.css';

// Les pastilles de navigation disent **vers quoi** une entrée renvoie. Elles ne
// nomment donc pas une nature et restent ce qu'elles sont. Là où leur cible en
// est une — l'accueil, le message de fin, sa variante nuit —, elles portent le
// dessin de cette nature : c'est le vocabulaire qui le veut, pas un hasard.
const BADGE_ICON_BY_KIND = {
  return: <CornerUpLeft />,
  'prompt-return': <UnfoldVertical />,
  'sequence-return': <ListTree />,
  home: <House />,
  'home-implicit': <House />,
  'home-none': <House />,
  'end-node': <Square />,
  'end-night': <Moon />,
  'end-node-home': <House />,
  'end-night-home': <House />,
  graph: <Diamond />,
  'auto-next': <span className="tree-auto-next-icon"><ChevronRight /><ChevronRight /></span>,
  continuation: <ArrowRight />,
};

const MAX_NAVIGATION_BADGE_SLOTS = 2;

function TreeInlineNameInput({ value, onChange, onCommit, onCancel }) {
  const inputRef = useRef(null);
  const cancelledRef = useRef(false);

  useEffect(() => {
    inputRef.current?.focus();
    inputRef.current?.select();
  }, []);

  return (
    <input
      ref={inputRef}
      className="tree-inline-name-input"
      value={value}
      aria-label="Renommer"
      onChange={(event) => onChange(event.target.value)}
      onBlur={() => {
        if (!cancelledRef.current) onCommit();
      }}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => {
        event.stopPropagation();
        if (event.nativeEvent.isComposing) return;
        if (event.key === 'Enter') {
          event.preventDefault();
          event.currentTarget.blur();
        } else if (event.key === 'Escape') {
          event.preventDefault();
          cancelledRef.current = true;
          onCancel();
        }
      }}
    />
  );
}

function TreeNodeInner({
  id,
  type,
  night = false,
  label,
  level,
  selected,
  hovered,
  cut,
  isAncestor,
  isActiveScope,
  isHoverScope,
  sortable,
  dragging,
  containerDroppableId,
  navigationBadges = [],
  showNavigationBadgeColumn = false,
  expanded,
  onToggleExpand,
  childCount,
  color,
  renaming,
  renameValue,
  onStartRename,
  onRenameChange,
  onRenameCommit,
  onRenameCancel,
  onSelect,
  onNavigationBadgeActivate,
  onContextMenu,
  onNodeHoverChange,
  hoverGuideScopeIds,
  hoverGuideLevel,
  hoverScopeEnabled,
  onHoverScope,
  isHoverGuide,
  dropTarget,
  suppressSortAnimation,
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id, disabled: !sortable || renaming });
  const { setNodeRef: setDropRef } = useDroppable({
    id: containerDroppableId ?? `disabled-container:${id}`,
    disabled: !containerDroppableId,
    data: {
      kind: 'container',
      containerId: type === 'root' ? null : id,
    },
  });

  const style = {
    ...(sortable
      ? {
          transform: suppressSortAnimation ? undefined : CSS.Transform.toString(transform),
          transition: suppressSortAnimation ? undefined : transition,
          opacity: cut ? 0.4 : isDragging ? 0.5 : 1,
        }
      : { opacity: cut ? 0.4 : 1 }),
    paddingLeft: `${getTreeIndent(level)}px`,
    ...getTreeGuideStyleVars({ level, hoverGuideLevel }),
    ...(color ? { '--tree-node-color': color } : {}),
  };

  const isDragActive = dragging && !isDragging;
  const showInsertBefore = isDragActive && dropTarget === 'before';
  const showInsertAfter = isDragActive && dropTarget === 'after';
  const showDropInside = isDragActive && dropTarget === 'inside';
  const showForbiddenDepth = isDragActive && dropTarget === 'forbidden-depth';
  const showForbiddenCycle = isDragActive && dropTarget === 'forbidden-cycle';

  const insertClass = showInsertBefore ? 'insert-before' : showInsertAfter ? 'insert-after' : '';
  const hasToggle = type === 'menu';
  const visibleBadgeCount = navigationBadges.length > MAX_NAVIGATION_BADGE_SLOTS
    ? MAX_NAVIGATION_BADGE_SLOTS - 1
    : MAX_NAVIGATION_BADGE_SLOTS;
  const visibleNavigationBadges = navigationBadges.slice(0, visibleBadgeCount);
  const hiddenNavigationBadges = navigationBadges.slice(visibleBadgeCount);
  const hasHiddenNavigationBadges = hiddenNavigationBadges.length > 0;
  const hiddenNavigationBadgeTitle = hasHiddenNavigationBadges
    ? hiddenNavigationBadges.map((badge) => badge.title).join(' · ')
    : '';

  // Le dessin vient de la table, pas d'une suite de conditions tenue ici. Le
  // repli est la lune : une entrée dont le type n'est pas une
  // nature connue est traitée comme un message de fin en mode nuit.
  const nature = hierarchicalNatureOf(type, { night }) ?? 'end-night';
  const resolvedIcon = (
    <NodeIcon
      workspaceMode={WORKSPACE_MODE_HIERARCHICAL}
      nature={nature}
      collapsed={type === 'menu' && !expanded}
    />
  );

  const handlePointerHover = onHoverScope && !dragging
    ? (e) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const guide = resolveHoverGuide({
          clientX: e.clientX,
          itemLeft: rect.left,
          level,
          guideScopeIds: hoverGuideScopeIds,
        });
        onHoverScope(guide.scopeId, guide.level, hoverScopeEnabled);
      }
    : undefined;

  return (
    <div
      ref={(node) => {
        setNodeRef(node);
        if (containerDroppableId) setDropRef(node);
      }}
      style={style}
      {...(sortable ? { ...attributes, ...listeners } : {})}
      className={[
        'tree-item',
        `tree-item--${type}`,
        selected ? 'active' : '',
        hovered ? 'is-linked-hover' : '',
        color ? 'is-colored' : '',
        isAncestor && !selected ? 'ancestor-sel' : '',
        isActiveScope && !selected ? 'active-scope' : '',
        isHoverScope && !selected ? 'hover-scope' : '',
        isHoverGuide ? 'hover-guide' : '',
        insertClass,
        showDropInside ? 'drop-target' : '',
        showForbiddenDepth ? 'drop-forbidden-depth' : '',
        showForbiddenCycle ? 'drop-forbidden-cycle' : '',
      ].filter(Boolean).join(' ')}
      aria-label={type === 'menu' ? `${label}, Dossier niveau ${level}` : undefined}
      title={showForbiddenDepth
        ? MENU_DEPTH_LIMIT_REACHED_MESSAGE
        : showForbiddenCycle
          ? MENU_CYCLE_MESSAGE
          : undefined}
      data-tree-node-id={id}
      {...(type === 'story' || type === 'menu' || type === 'root'
        ? { 'data-media-node-id': id, 'data-media-node-type': type }
        : {})}
      onClick={(e) => onSelect(id, e)}
      onDoubleClick={(event) => {
        if (!onStartRename || event.target.closest('button, input, .badge-nav')) return;
        event.preventDefault();
        event.stopPropagation();
        onStartRename(id, type, label);
      }}
      onContextMenu={onContextMenu ? (e) => { e.preventDefault(); onContextMenu(e, id, type); } : undefined}
      onPointerEnter={(event) => {
        handlePointerHover?.(event);
        if (!dragging) onNodeHoverChange?.(id, true);
      }}
      onPointerMove={handlePointerHover}
      onPointerLeave={() => onNodeHoverChange?.(id, false)}
    >
      <span className="tree-depth-guides" aria-hidden="true" />
      <span className="tree-active-branch-guide" aria-hidden="true" />
      <span className="tree-hover-branch-guide" aria-hidden="true" />
      {hasToggle ? (
        <button
          className={`tree-chevron${expanded ? ' tree-chevron--expanded' : ''}`}
          onClick={(e) => { e.stopPropagation(); onToggleExpand?.(id); }}
          onPointerDown={(e) => e.stopPropagation()}
          tabIndex={-1}
        />
      ) : (
        <span className="tree-chevron-spacer" />
      )}
      <div className="tree-item-body">
        <div className={`ti-badges${showNavigationBadgeColumn ? ' has-column' : ''}${navigationBadges.length === 0 ? ' is-empty' : ''}${hasHiddenNavigationBadges ? ' is-compact' : ''}`}>
          {visibleNavigationBadges.map((badge) => (
            <Tooltip key={badge.key} text={badge.title}>
              {badge.action ? (
                <button
                  type="button"
                  className={`badge-nav badge-nav--${badge.kind}${badge.status ? ` badge-nav--${badge.status}` : ''}`}
                  aria-label={badge.title}
                  onPointerDown={(event) => event.stopPropagation()}
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    onNavigationBadgeActivate?.(badge.action);
                  }}
                >
                  {BADGE_ICON_BY_KIND[badge.kind] ?? badge.label}
                </button>
              ) : (
                <span
                  className={`badge-nav badge-nav--${badge.kind}${badge.status ? ` badge-nav--${badge.status}` : ''}`}
                  onPointerDown={(event) => event.stopPropagation()}
                >
                  {BADGE_ICON_BY_KIND[badge.kind] ?? badge.label}
                </span>
              )}
            </Tooltip>
          ))}
          {hasHiddenNavigationBadges ? (
            <Tooltip text={hiddenNavigationBadgeTitle} wrap>
              <span
                className="badge-nav badge-nav--more"
                onPointerDown={(e) => e.stopPropagation()}
              >
                +{hiddenNavigationBadges.length}
              </span>
            </Tooltip>
          ) : null}
        </div>
        <span className="ti-icon">{resolvedIcon}</span>
        {renaming ? (
          <TreeInlineNameInput
            value={renameValue}
            onChange={onRenameChange}
            onCommit={onRenameCommit}
            onCancel={onRenameCancel}
          />
        ) : (
          <span className="ti-label">{label}</span>
        )}
        {type === 'zip' && <span className="badge-zip">ZIP</span>}
        {type === 'menu' && level > 6 ? (
          <span className="badge-depth" title={`Dossier niveau ${level}`}>N{level}</span>
        ) : null}
        {hasToggle && !expanded && childCount > 0 && (
          <span className="badge-count">{childCount}</span>
        )}
      </div>
    </div>
  );
}

export const TreeNode = memo(TreeNodeInner, (prev, next) => (
  prev.id === next.id
  && prev.type === next.type
  && prev.night === next.night
  && prev.label === next.label
  && prev.level === next.level
  && prev.selected === next.selected
  && prev.hovered === next.hovered
  && prev.cut === next.cut
  && prev.isAncestor === next.isAncestor
  && prev.isActiveScope === next.isActiveScope
  && prev.isHoverScope === next.isHoverScope
  && prev.isHoverGuide === next.isHoverGuide
  && prev.dragging === next.dragging
  && prev.containerDroppableId === next.containerDroppableId
  && prev.showNavigationBadgeColumn === next.showNavigationBadgeColumn
  && prev.navigationBadges === next.navigationBadges
  && prev.expanded === next.expanded
  && prev.onToggleExpand === next.onToggleExpand
  && prev.childCount === next.childCount
  && prev.color === next.color
  && prev.renaming === next.renaming
  && prev.renameValue === next.renameValue
  && prev.onStartRename === next.onStartRename
  && prev.onRenameChange === next.onRenameChange
  && prev.onRenameCommit === next.onRenameCommit
  && prev.onRenameCancel === next.onRenameCancel
  && prev.onSelect === next.onSelect
  && prev.onNavigationBadgeActivate === next.onNavigationBadgeActivate
  && prev.onContextMenu === next.onContextMenu
  && prev.onNodeHoverChange === next.onNodeHoverChange
  && prev.hoverGuideScopeIds === next.hoverGuideScopeIds
  && prev.hoverGuideLevel === next.hoverGuideLevel
  && prev.hoverScopeEnabled === next.hoverScopeEnabled
  && prev.onHoverScope === next.onHoverScope
  && prev.dropTarget === next.dropTarget
  && prev.suppressSortAnimation === next.suppressSortAnimation
));

sources.src/components/TreePanel/TreePanel.jsx:
import { DndContext, DragOverlay } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import { Fragment, useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { TreeNode } from './TreeNode';
import { TreeSearchBar } from './TreeSearchBar';
import { TreeDragOverlay } from './TreeDragOverlay';
import { ContextMenu } from './ContextMenu';
import { useTreeDnd } from './useTreeDnd';
import { useTreeSelection } from './useTreeSelection';
import { useTreeClipboard } from './useTreeClipboard';
import { useTreeNavigationBadges } from './useTreeNavigationBadges';
import { useTreeSearch } from './useTreeSearch';
import { buildTreeContextActions } from './treeContextMenuActions';
import {
  buildGuideScopeIdsById,
  getNextHoverGuide,
  isEntryInHoverGuide,
  sameHoverGuide,
} from './treeGuides';
import { END_NODE_ID, EMPTY_BADGES } from './treePanelConstants';
import { canInlineRenameTreeNode, getInlineRenameFields } from './treeInlineRename';
import { useMediaTransfer } from '../../store/MediaTransferContext';
import { findShortcutAction, getCurrentShortcuts } from '../../store/keyboardShortcuts';
import { isEditableTarget } from '../../utils/shortcutTarget';
import { useShortcutLabels } from '../../store/ShortcutLabelsContext';
import {
  countDescendants,
  resolveDropTargetForNode,
} from '../tree/treeOperations';
import { buildRefDisplay } from '../tree/refDisplay';
import { hasVisibleEndNode } from '../../store/generatedNavigation';
import './TreePanel.css';

// Les natures qu'on duplique, comme le menu contextuel de l'arbre.
const DUPLICABLE_TREE_TYPES = Object.freeze(['menu', 'story', 'zip']);

export { END_NODE_ID };

function scrollTreeNodeIntoView(node, behavior = 'auto') {
  if (!node) return;
  node.scrollIntoView({ block: 'nearest', behavior });
  const visibleContent = node.querySelector('.tree-item-body') ?? node;
  visibleContent.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior });
}

export function TreePanel({
  project, projectType, selectedId, selectedIds, onSelect, onReorder, onMoveToMenu,
  onAddMenu, onAddStory, onImportFolder, onDeleteMenu, onDeleteItem, onUnpackZip, onSimulateZip,
  onBulkDeleteItems, onBulkUpdateItems,
  onPasteEntries, onCutPasteEntries, onSetMenuAsRoot, onDemoteRootToMenu, onSelectionChange, onDuplicate, onSetNodeColor,
  onRenameNode,
  onOpenAutoNextSettings,
  onAddEndNode, onRemoveEndNode, onSimulateNode,
  onOpenMediaAudioTool,
  validationIssues: validationIssuesProp, projectIndex,
  treeSearchFocusTrigger = 0,
  selectionRevealRequest = null,
  hoveredNodeId = null,
  onNodeHoverChange,
  showNavigationBadges = true,
  showTreeGuides = true,
}) {
  const { activeDropZone } = useMediaTransfer();
  const [ctxMenu, setCtxMenu] = useState(null);
  const [collapsedIds, setCollapsedIds] = useState(new Set());
  const [hoverScopeParentId, setHoverScopeParentId] = useState(null);
  const [hoverGuide, setHoverGuide] = useState(null);
  const [inlineRename, setInlineRename] = useState(null);
  const shortcutLabels = useShortcutLabels();
  const osDropHover = activeDropZone === 'treepanel';

  const isExpanded = useCallback((id) => !collapsedIds.has(id), [collapsedIds]);
  const treeScrollRef = useRef(null);

  const rootEntries = project.rootEntries ?? [];
  const validationIssues = validationIssuesProp ?? [];

  const flatNodes = useMemo(() => {
    const nodes = [{ id: 'root', type: 'root', level: 0 }];
    if (projectType === 'pack') {
      nodes.push(...projectIndex.flatEntries.map((entry) => ({
        id: entry.id,
        type: entry.type,
        level: entry.level,
      })));
      if (hasVisibleEndNode(project)) {
        nodes.push({ id: END_NODE_ID, type: END_NODE_ID, level: 0 });
      }
    }
    return nodes;
  }, [project, projectIndex, projectType]);
  const flatNodeIndexById = useMemo(
    () => new Map(flatNodes.map((node, index) => [node.id, index])),
    [flatNodes],
  );
  const getEntry = useCallback((entryId) => projectIndex.entryById.get(entryId) ?? null, [projectIndex]);
  const getParentId = useCallback((entryId) => projectIndex.parentMenuById.get(entryId) ?? null, [projectIndex]);
  const {
    anchorIdRef,
    callOnSelect,
    handleNodeSelect,
  } = useTreeSelection({
    selectedIds,
    selectedId,
    onSelect,
    onSelectionChange,
    flatNodes,
    flatNodeIndexById,
  });

  const handleToggleExpand = useCallback((id) => {
    // Dossier dans une multi-selection : on applique le meme repli/depli a tous
    // les dossiers selectionnes. L'etat cible suit le dossier sur lequel on clique.
    const targets = selectedIds.has(id) && selectedIds.size > 1
      ? [...selectedIds].filter((sid) => getEntry(sid)?.type === 'menu')
      : [id];
    setCollapsedIds((prev) => {
      const next = new Set(prev);
      const willCollapse = !next.has(id);
      for (const folderId of (targets.length > 0 ? targets : [id])) {
        if (willCollapse) next.add(folderId);
        else next.delete(folderId);
      }
      return next;
    });
  }, [selectedIds, getEntry]);

  const handleNavigationBadgeActivate = useCallback((action) => {
    if (action === 'open-auto-next-settings') onOpenAutoNextSettings?.();
  }, [onOpenAutoNextSettings]);

  const ancestorIds = useMemo(() => {
    const ancestors = new Set();
    for (const id of selectedIds) {
      if (id === 'root' || id === END_NODE_ID) continue;
      let parentId = getParentId(id);
      while (parentId != null) {
        ancestors.add(parentId);
        parentId = getParentId(parentId);
      }
    }
    return ancestors;
  }, [selectedIds, getParentId]);

  const activeScopeParentId = useMemo(() => {
    if (!selectedId || selectedId === 'root' || selectedId === END_NODE_ID) return null;
    return getParentId(selectedId) ?? 'root';
  }, [selectedId, getParentId]);

  const guideScopeIdsById = useMemo(
    () => buildGuideScopeIdsById(projectIndex),
    [projectIndex],
  );

  const clearHoverScope = useCallback(() => {
    setHoverScopeParentId(null);
    setHoverGuide(null);
  }, []);

  const handleStartRename = useCallback((id, type, name) => {
    if (!canInlineRenameTreeNode(type)) return;
    setInlineRename({ id, type, originalName: name ?? '', draftName: name ?? '' });
  }, []);

  const handleRenameChange = useCallback((draftName) => {
    setInlineRename((current) => (current ? { ...current, draftName } : current));
  }, []);

  const handleRenameCancel = useCallback(() => {
    setInlineRename(null);
  }, []);

  const handleRenameCommit = useCallback(() => {
    if (!inlineRename) return;
    const fields = getInlineRenameFields(inlineRename.originalName, inlineRename.draftName);
    setInlineRename(null);
    if (fields) onRenameNode?.(inlineRename.id, inlineRename.type, fields);
  }, [inlineRename, onRenameNode]);

  const handleHoverScope = useCallback((parentScopeId, level, enableScope) => {
    const nextGuide = getNextHoverGuide(parentScopeId, level);
    setHoverGuide((prev) => (
      sameHoverGuide(prev, nextGuide)
        ? prev
        : nextGuide
    ));
    const nextScopeParentId = enableScope ? (parentScopeId ?? null) : null;
    setHoverScopeParentId((prev) => (prev === nextScopeParentId ? prev : nextScopeParentId));
  }, []);

  const { navigationBadgesById, rootNavigationBadges, endNodeNavigationBadges, hasEndNode } = useTreeNavigationBadges({
    project,
    projectIndex,
    projectType,
    showNavigationBadges,
    validationIssues,
  });

  const {
    searchActive,
    setSearchActive,
    searchTerm,
    setSearchTerm,
    searchInputRef,
    visibleIds,
    usedColors,
    selectedColors: selectedSearchColors,
    toggleColor: toggleSearchColor,
    clearSearch,
  } = useTreeSearch({ project, projectIndex, projectType, treeSearchFocusTrigger });

  const lastRevealRequestRef = useRef(null);
  useEffect(() => {
    const requestId = selectionRevealRequest?.requestId;
    const targetId = selectionRevealRequest?.id;
    if (!requestId || !targetId || lastRevealRequestRef.current === requestId) return undefined;

    if (visibleIds && targetId !== 'root' && targetId !== END_NODE_ID && !visibleIds.has(targetId)) {
      clearSearch();
    }

    if (targetId !== 'root' && targetId !== END_NODE_ID) {
      setCollapsedIds((current) => {
        const next = new Set(current);
        let changed = false;
        let parentId = getParentId(targetId);
        while (parentId != null) {
          changed = next.delete(parentId) || changed;
          parentId = getParentId(parentId);
        }
        return changed ? next : current;
      });
    }

    let frameId = null;
    let attempts = 0;
    const reveal = () => {
      const host = treeScrollRef.current;
      const target = host
        ? [...host.querySelectorAll('[data-tree-node-id]')]
          .find((node) => node.dataset.treeNodeId === String(targetId))
        : null;
      if (target) {
        lastRevealRequestRef.current = requestId;
        scrollTreeNodeIntoView(target, 'smooth');
        return;
      }
      attempts += 1;
      if (attempts < 3) frameId = requestAnimationFrame(reveal);
      else lastRevealRequestRef.current = requestId;
    };
    frameId = requestAnimationFrame(reveal);
    return () => {
      if (frameId != null) cancelAnimationFrame(frameId);
    };
  }, [clearSearch, getParentId, selectionRevealRequest, visibleIds]);

  useEffect(() => {
    const host = treeScrollRef.current;
    if (!host || !selectedId) return;
    const target = [...host.querySelectorAll('[data-tree-node-id]')]
      .find((node) => node.dataset.treeNodeId === String(selectedId));
    scrollTreeNodeIntoView(target);
  }, [selectedId]);

  const {
    clipboardRef,
    cutIds,
    getTopLevelSelected,
    handleCopy,
    handleCut,
    handlePaste,
    handlePasteMedia,
    handleReplaceAudio,
    deleteSelectedNodes,
  } = useTreeClipboard({
    selectedId,
    selectedIds,
    getEntry,
    getParentId,
    onPasteEntries,
    onCutPasteEntries,
    onBulkDeleteItems,
    onRemoveEndNode,
    onSelectionChange,
    callOnSelect,
  });

  const getContainerEntries = useCallback((containerId) => {
    if (containerId == null) return rootEntries;
    const container = getEntry(containerId);
    return container?.type === 'menu' ? (container.children ?? []) : [];
  }, [getEntry, rootEntries]);

  const {
    activeId,
    dropInfo,
    sensors,
    collisionDetection,
    handleDragStart,
    handleDragMove,
    handleDragEnd,
    handleDragCancel,
  } = useTreeDnd({
    project,
    projectIndex,
    selectedIds,
    flatNodes,
    getEntry,
    getParentId,
    getContainerEntries,
    onReorder,
    onMoveToMenu,
  });

  useEffect(() => {
    if (activeId) {
      setHoverScopeParentId(null);
      setHoverGuide(null);
    }
  }, [activeId]);

  function handleKeyDown(e) {
    if (!selectedId) return;
    const idx = flatNodeIndexById.get(selectedId) ?? -1;
    if (idx === -1) return;

    // Navigation a11y standard — non configurable.
    if (e.key === 'ArrowUp' || (e.key === 'Tab' && e.shiftKey)) {
      e.preventDefault();
      if (idx > 0) handleNodeSelect(flatNodes[idx - 1].id, e.shiftKey ? e : null);
      return;
    }
    if (e.key === 'ArrowDown' || e.key === 'Tab') {
      e.preventDefault();
      if (idx < flatNodes.length - 1) handleNodeSelect(flatNodes[idx + 1].id, e.shiftKey ? e : null);
      return;
    }

    // Les commandes de sélection, partagées avec le diagramme et le graphe :
    // une touche reconfigurée l'est pour les trois surfaces. Un champ ouvert
    // dans l'arbre — le renommage en place — garde ses frappes.
    if (isEditableTarget(e.target)) return;
    const actionId = findShortcutAction(e, getCurrentShortcuts(), 'selection');
    if (!actionId) return;
    const entry = getEntry(selectedId);
    // Dupliquer et renommer visent un seul nœud, comme leurs entrées du menu
    // contextuel : sans nœud nommable ou duplicable, la touche reste libre.
    if (actionId === 'selectionDuplicate') {
      if (!onDuplicate || selectedIds.size !== 1 || !DUPLICABLE_TREE_TYPES.includes(entry?.type)) return;
      e.preventDefault();
      onDuplicate(selectedId);
      return;
    }
    if (actionId === 'selectionRename') {
      if (selectedIds.size !== 1 || !entry || !canInlineRenameTreeNode(entry.type)) return;
      e.preventDefault();
      handleStartRename(entry.id, entry.type, entry.name);
      return;
    }
    e.preventDefault();
    if (actionId === 'selectionCopy') handleCopy();
    else if (actionId === 'selectionCut') handleCut();
    else if (actionId === 'selectionPaste') handlePaste();
    else if (actionId === 'selectionDelete') void deleteSelectedNodes();
  }

  const handleContextMenu = useCallback((e, nodeId, nodeType) => {
    e.preventDefault();
    e.stopPropagation();
    if (projectType !== 'pack') return;
    if (!selectedIds.has(nodeId)) {
      // Emettre la selection AVANT callOnSelect : le menu doit refleter le seul
      // noeud vise, pas une ancienne multi (evite une action groupee surprise).
      onSelectionChange?.(new Set([nodeId]));
      anchorIdRef.current = nodeId;
      callOnSelect(nodeId);
    }
    setCtxMenu({ x: e.clientX, y: e.clientY, nodeId, nodeType });
  }, [anchorIdRef, callOnSelect, onSelectionChange, projectType, selectedIds]);

  function renderEntries(entries, level, parentMenu = null, { sortable = true } = {}) {
    const filtered = visibleIds ? entries.filter((e) => visibleIds.has(e.id)) : entries;
    if (!filtered?.length) return null;
    const parentScopeId = parentMenu?.id ?? 'root';
    const content = filtered.map((entry) => (
          <Fragment key={entry.id}>
            <TreeNode
              id={entry.id}
              type={entry.type}
              label={entry.type === 'ref' ? buildRefDisplay(entry, projectIndex.entryById).label : entry.name}
              level={level}
              selected={selectedIds.has(entry.id)}
              hovered={hoveredNodeId === entry.id}
              cut={cutIds.has(entry.id)}
              color={entry.treeColor}
              renaming={inlineRename?.id === entry.id}
              renameValue={inlineRename?.id === entry.id ? inlineRename.draftName : ''}
              onStartRename={canInlineRenameTreeNode(entry.type) ? handleStartRename : undefined}
              onRenameChange={inlineRename?.id === entry.id ? handleRenameChange : undefined}
              onRenameCommit={inlineRename?.id === entry.id ? handleRenameCommit : undefined}
              onRenameCancel={inlineRename?.id === entry.id ? handleRenameCancel : undefined}
              isAncestor={ancestorIds.has(entry.id)}
              isActiveScope={activeScopeParentId === parentScopeId}
              isHoverScope={hoverScopeParentId === parentScopeId}
              isHoverGuide={isEntryInHoverGuide({
                entryId: entry.id,
                level,
                hoverGuide,
                guideScopeIdsById,
              })}
              dragging={!!activeId}
              containerDroppableId={sortable && entry.type === 'menu' ? `container:${entry.id}` : null}
              navigationBadges={navigationBadgesById.get(entry.id) ?? EMPTY_BADGES}
              showNavigationBadgeColumn={showNavigationBadgeColumn}
              expanded={visibleIds !== null || isExpanded(entry.id)}
              onToggleExpand={handleToggleExpand}
              childCount={countDescendants(entry)}
              sortable={sortable}
              dropTarget={resolveDropTargetForNode(entry.id, entry.type, dropInfo)}
              suppressSortAnimation={suppressSortAnimation}
              onSelect={handleNodeSelect}
              onContextMenu={handleContextMenu}
              onNodeHoverChange={onNodeHoverChange}
              hoverGuideScopeIds={guideScopeIdsById.get(entry.id)}
              hoverGuideLevel={hoverGuide?.level ?? null}
              hoverScopeEnabled={sortable && entry.type === 'menu'}
              onHoverScope={sortable ? handleHoverScope : undefined}
            />
            {entry.type === 'menu' && (visibleIds !== null || isExpanded(entry.id))
              ? renderEntries(entry.children ?? [], level + 1, entry, { sortable })
              : null}
          </Fragment>
    ));
    return sortable ? (
      <SortableContext items={filtered.map((entry) => entry.id)} strategy={verticalListSortingStrategy}>
        {content}
      </SortableContext>
    ) : content;
  }

  const nightModeActive = !!project.globalOptions?.nightMode;
  const showNavigationBadgeColumn = projectType === 'pack' && showNavigationBadges;

  const prevHasEndNodeRef = useRef(hasEndNode);
  useEffect(() => {
    if (!prevHasEndNodeRef.current && hasEndNode && treeScrollRef.current) {
      treeScrollRef.current.scrollTop = treeScrollRef.current.scrollHeight;
    }
    prevHasEndNodeRef.current = hasEndNode;
  }, [hasEndNode]);

  const activeEntry = activeId ? getEntry(activeId) : null;
  // Garde le dossier survolé stable pendant qu'on vise : on fige la sort-animation
  // dès qu'on survole un dossier (pas seulement une fois "dedans"), pour qu'il ne
  // glisse plus sous le curseur et qu'on déborde moins en avant/après.
  const overEntry = activeId && dropInfo.targetId ? getEntry(dropInfo.targetId) : null;
  const suppressSortAnimation = !!activeId && !dropInfo.isContainer
    && (dropInfo.position === 'inside' || overEntry?.type === 'menu');

  return (
    <>
      <DndContext
        sensors={sensors}
        collisionDetection={collisionDetection}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        <div className="tree-shell" data-os-drop-zone="treepanel">
          {projectType === 'pack' && searchActive ? (
            <TreeSearchBar
              searchTerm={searchTerm}
              setSearchTerm={setSearchTerm}
              setSearchActive={setSearchActive}
              inputRef={searchInputRef}
              usedColors={usedColors}
              selectedColors={selectedSearchColors}
              onToggleColor={toggleSearchColor}
              onClearSearch={clearSearch}
            />
          ) : null}
          <div
            ref={treeScrollRef}
            className={`tree${showTreeGuides ? '' : ' tree--no-guides'}`}
            tabIndex={0}
            onPointerDownCapture={(event) => {
              if (event.target.closest('.tree-inline-name-input')) return;
              treeScrollRef.current?.focus({ preventScroll: true });
            }}
            onKeyDown={handleKeyDown}
            onContextMenu={(e) => handleContextMenu(e, 'root', 'root-bg')}
            onPointerLeave={() => {
              clearHoverScope();
              if (hoveredNodeId) onNodeHoverChange?.(hoveredNodeId, false);
            }}
            style={{ outline: 'none' }}
            data-media-node-id="root"
            data-media-node-type="root"
          >
            <TreeNode
              id="root"
              type="root"
              label={projectType === 'pack'
                ? (project.rootName || 'Menu racine')
                : (project.projectName || 'Mon histoire')}
              level={0}
              selected={selectedIds.has('root')}
              hovered={hoveredNodeId === 'root'}
              color={project.treeColor}
              dragging={!!activeId}
              containerDroppableId="container:root"
              navigationBadges={rootNavigationBadges}
              onNavigationBadgeActivate={handleNavigationBadgeActivate}
              showNavigationBadgeColumn={showNavigationBadgeColumn}
              dropTarget={resolveDropTargetForNode('root', 'root', dropInfo)}
              suppressSortAnimation={suppressSortAnimation}
              onSelect={handleNodeSelect}
              onContextMenu={handleContextMenu}
              onNodeHoverChange={onNodeHoverChange}
            />

            {projectType === 'pack' ? renderEntries(rootEntries, 1, null) : null}

            {hasEndNode ? <div className="tree-end-node-sep" /> : null}
            {hasEndNode ? (
              <div
                className="tree-end-node-wrap"
                onContextMenu={(e) => handleContextMenu(e, END_NODE_ID, END_NODE_ID)}
              >
                <TreeNode
                  id={END_NODE_ID}
                  type="end-node"
                  night={nightModeActive}
                  label={`${project.endNodeName || 'Message de fin'}${nightModeActive ? ' (mode nuit)' : ''}`}
                  level={0}
                  selected={selectedIds.has(END_NODE_ID)}
                  hovered={hoveredNodeId === END_NODE_ID}
                  dragging={false}
                  navigationBadges={showNavigationBadgeColumn ? endNodeNavigationBadges : EMPTY_BADGES}
                  showNavigationBadgeColumn={showNavigationBadgeColumn}
                  onSelect={handleNodeSelect}
                  onContextMenu={handleContextMenu}
                  onNodeHoverChange={onNodeHoverChange}
                />
              </div>
            ) : null}
          </div>

        {osDropHover && (
          <div className="tree-os-drop-overlay">
            Déposer pour ajouter au projet
          </div>
        )}
        </div>

        <DragOverlay>
          <TreeDragOverlay entry={activeEntry} />
        </DragOverlay>
      </DndContext>

      {ctxMenu && (
        <ContextMenu
          x={ctxMenu.x}
          y={ctxMenu.y}
          onClose={() => setCtxMenu(null)}
          actions={buildTreeContextActions({
            shortcutLabels,
            nodeId: ctxMenu.nodeId,
            nodeType: ctxMenu.nodeType,
            project,
            projectIndex,
            projectType,
            selectedIds,
            getEntry,
            getParentId,
            clipboardRef,
            getTopLevelSelected,
            handleCopy,
            handleCut,
            handlePaste,
            handlePasteMedia,
            handleReplaceAudio,
            callOnSelect,
            onSelectionChange,
            onAddMenu,
            onAddStory,
            onImportFolder,
            onAddEndNode,
            onRemoveEndNode,
            onDemoteRootToMenu,
            onSetMenuAsRoot,
            onSimulateZip,
            onUnpackZip,
            onSimulateNode,
            onMoveToMenu,
            onDuplicate,
            onDeleteMenu,
            onDeleteItem,
            onBulkDeleteItems,
            onBulkUpdateItems,
            onSetNodeColor,
            onOpenMediaAudioTool,
            closeContextMenu: () => setCtxMenu(null),
          })}
        />
      )}
    </>
  );
}

