import { buildStructureProjection, getStructureEdgeId } from './structurePresentation.js';

const END_NODE_ID = 'end-node';

function measureTree(node, metrics, horizontalGap) {
  const nodeWidth = node.entry.type === 'root' ? metrics.rootWidth : metrics.nodeWidth;
  const children = node.children.map((child) => measureTree(child, metrics, horizontalGap));
  const childrenWidth = children.length
    ? children.reduce((sum, child) => sum + child.subtreeWidth, 0) + (horizontalGap * (children.length - 1))
    : 0;
  return {
    ...node,
    nodeWidth,
    children,
    subtreeWidth: Math.max(nodeWidth, childrenWidth),
    childrenWidth,
  };
}

function maxDepth(node) {
  return node.children.reduce((depth, child) => Math.max(depth, maxDepth(child)), node.depth);
}

export function getStructureLevelLayout(project, metrics, options = {}) {
  const projection = buildStructureProjection(project, options);
  const horizontalGap = Math.max(18, metrics.colGap * 1.5);
  const rowPitch = metrics.nodeHeight + Math.max(74, metrics.rowGap);
  const labelGutter = 46;
  const padX = metrics.padX + labelGutter;
  const padY = metrics.padY + 24;
  const measuredRoot = measureTree(projection, metrics, horizontalGap);
  const nodes = [];
  const edges = [];

  function place(node, left) {
    const x = left + ((node.subtreeWidth - node.nodeWidth) / 2);
    const y = padY + (node.depth * rowPitch);
    nodes.push({
      entry: node.entry,
      x,
      y,
      width: node.nodeWidth,
      height: metrics.nodeHeight,
      depth: node.depth,
      parentId: node.parentId,
    });

    if (!node.children.length) return;
    let childLeft = left + ((node.subtreeWidth - node.childrenWidth) / 2);
    for (const child of node.children) {
      const childX = childLeft + ((child.subtreeWidth - child.nodeWidth) / 2);
      const childY = padY + (child.depth * rowPitch);
      const edge = {
        id: `structure:${node.id}:${child.id}`,
        from: node.id,
        to: child.id,
        kind: child.entry.type === 'story' ? 'story' : child.entry.type === 'story-group' ? 'story-group' : 'structural',
        x1: x + (node.nodeWidth / 2),
        y1: y + metrics.nodeHeight,
        x2: childX + (child.nodeWidth / 2),
        y2: childY,
        depth: child.depth,
      };
      edge.midY = edge.y1 + ((edge.y2 - edge.y1) / 2);
      edge.id = getStructureEdgeId(edge);
      edges.push(edge);
      place(child, childLeft);
      childLeft += child.subtreeWidth + horizontalGap;
    }
  }

  place(measuredRoot, padX);
  const depthCount = maxDepth(measuredRoot) + 1;
  const width = measuredRoot.subtreeWidth + (padX * 2);
  let height = padY + ((depthCount - 1) * rowPitch) + metrics.nodeHeight + metrics.padY + 28;
  const bands = Array.from({ length: depthCount }, (_, depth) => ({
    depth,
    label: `N${depth}`,
    y: padY + (depth * rowPitch) - 20,
    height: metrics.nodeHeight + 40,
  }));

  const hiddenStoryGroupByStoryId = new Map();
  for (const node of nodes) {
    if (node.entry.type !== 'story-group') continue;
    node.entry.storyIds?.forEach((storyId) => hiddenStoryGroupByStoryId.set(storyId, node.entry.id));
  }

  const hasEndNode = !!(
    project.nightModeAudio
    || project.globalOptions?.nightMode
    || project.globalOptions?.endNode
  );
  let endNodeX = null;
  let endNodeY = null;
  if (hasEndNode) {
    const endNodeWidth = metrics.rootWidth;
    const endNodeHeight = metrics.nodeHeight;
    const endBandGap = Math.max(28, metrics.rowGap * 0.38);
    endNodeY = height + endBandGap;
    endNodeX = Math.round((width - endNodeWidth) / 2);
    bands.push({
      depth: 'end',
      kind: 'after-reading',
      y: endNodeY - 18,
      height: endNodeHeight + 34,
    });
    nodes.push({
      entry: {
        id: END_NODE_ID,
        type: 'end-node',
        name: project.endNodeName || 'Message de fin',
        icon: project.globalOptions?.nightMode ? 'moon' : 'stop',
      },
      x: endNodeX,
      y: endNodeY,
      width: endNodeWidth,
      height: endNodeHeight,
      depth: null,
      parentId: null,
    });
    height = endNodeY + endNodeHeight + metrics.padY + 18;
  }

  return {
    width,
    height,
    metrics,
    nodes,
    edges,
    groups: [],
    bands,
    hasEndNode,
    endNodeX: endNodeX == null ? undefined : endNodeX + (nodes.at(-1).width / 2),
    endNodeY: endNodeY ?? undefined,
    endNodeHeight: hasEndNode ? nodes.at(-1).height : undefined,
    hiddenStoryGroupByStoryId,
    isLevelLayout: true,
  };
}

const STORY_GROUP_PREFIX = 'story-group:';

export function getStoryGroupId(parentId) {
  return `${STORY_GROUP_PREFIX}${parentId}`;
}

export function toggleStoryGroup(currentGroupIds, requestedGroupId) {
  const nextGroupIds = new Set(currentGroupIds ?? []);
  if (nextGroupIds.has(requestedGroupId)) nextGroupIds.delete(requestedGroupId);
  else nextGroupIds.add(requestedGroupId);
  return nextGroupIds;
}

function getChildren(entry) {
  if (entry.type === 'root' || entry.type === 'menu') return entry.children ?? [];
  return [];
}

function projectEntry(entry, depth, options) {
  const projected = {
    id: entry.id,
    entry,
    depth,
    parentId: options.parentId ?? null,
    children: [],
  };
  const children = getChildren(entry);
  const containers = children.filter((child) => child.type === 'menu' || child.type === 'zip');
  const otherLeaves = children.filter((child) => child.type !== 'menu' && child.type !== 'zip' && child.type !== 'story');
  const stories = children.filter((child) => child.type === 'story');

  projected.children.push(...containers.map((child) => projectEntry(child, depth + 1, {
    ...options,
    parentId: entry.id,
  })));
  projected.children.push(...otherLeaves.map((child) => projectEntry(child, depth + 1, {
    ...options,
    parentId: entry.id,
  })));

  const groupId = getStoryGroupId(entry.id);
  const storiesAreExpanded = options.expandedStoryGroupIds?.has(groupId);
  const storiesAreGrouped = stories.length > 0
    && !storiesAreExpanded
    && (entry.type === 'menu' || stories.length > 1);
  if (storiesAreGrouped) {
    projected.children.push({
      id: groupId,
      entry: {
        id: groupId,
        type: 'story-group',
        name: `${stories.length} histoires`,
        storyCount: stories.length,
        storyIds: stories.map((story) => story.id),
        parentId: entry.id,
      },
      depth: depth + 1,
      parentId: entry.id,
      children: [],
    });
  } else {
    projected.children.push(...stories.map((story) => projectEntry(story, depth + 1, {
      ...options,
      parentId: entry.id,
    })));
  }

  return projected;
}

export function buildStructureProjection(project, options = {}) {
  return projectEntry({
    id: 'root',
    type: 'root',
    name: project.projectType === 'simple'
      ? (project.projectName || 'Mon histoire')
      : (project.rootName || 'Menu racine'),
    treeColor: project.treeColor ?? null,
    children: project.rootEntries ?? [],
  }, 0, {
    expandedStoryGroupIds: options.expandedStoryGroupIds ?? new Set(),
    parentId: null,
  });
}

export function getStructureEdgeId(edge) {
  return edge.id ?? `structure:${edge.from}:${edge.to}`;
}

export function buildStructureFocus(edges, activeEdgeId, labelById = new Map()) {
  if (!activeEdgeId) return null;
  const edgeById = new Map(edges.map((edge) => [getStructureEdgeId(edge), edge]));
  const activeEdge = edgeById.get(activeEdgeId);
  if (!activeEdge) return null;

  const parentEdgeByChild = new Map();
  const childEdgesByParent = new Map();
  for (const edge of edges) {
    parentEdgeByChild.set(edge.to, edge);
    const siblings = childEdgesByParent.get(edge.from) ?? [];
    siblings.push(edge);
    childEdgesByParent.set(edge.from, siblings);
  }

  const pathEdges = [activeEdge];
  const visited = new Set([activeEdge.to]);
  let currentId = activeEdge.from;
  while (currentId && !visited.has(currentId)) {
    visited.add(currentId);
    const parentEdge = parentEdgeByChild.get(currentId);
    if (!parentEdge) break;
    pathEdges.unshift(parentEdge);
    currentId = parentEdge.from;
  }

  const pathEdgeIds = new Set(pathEdges.map(getStructureEdgeId));
  const pathNodeIds = new Set();
  for (const edge of pathEdges) {
    pathNodeIds.add(edge.from);
    pathNodeIds.add(edge.to);
  }
  const siblingNodeIds = new Set(
    (childEdgesByParent.get(activeEdge.from) ?? [])
      .filter((edge) => edge.to !== activeEdge.to)
      .map((edge) => edge.to),
  );
  const siblingEdgeIds = new Set(
    (childEdgesByParent.get(activeEdge.from) ?? [])
      .filter((edge) => edge.to !== activeEdge.to)
      .map(getStructureEdgeId),
  );
  const breadcrumbIds = [pathEdges[0]?.from, ...pathEdges.map((edge) => edge.to)].filter(Boolean);
  const breadcrumb = breadcrumbIds.map((id) => labelById.get(id) ?? id);

  return {
    activeEdge,
    activeEdgeId,
    pathEdges,
    pathEdgeIds,
    pathNodeIds,
    siblingNodeIds,
    siblingEdgeIds,
    breadcrumbIds,
    breadcrumb,
    targetDepth: Math.max(0, breadcrumbIds.length - 1),
    parentLabel: labelById.get(activeEdge.from) ?? activeEdge.from,
    targetLabel: labelById.get(activeEdge.to) ?? activeEdge.to,
  };
}

